create table if not exists public.koda_conversations (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, title text not null default 'Nova conversa', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.koda_messages (id uuid primary key default gen_random_uuid(), conversation_id uuid not null references public.koda_conversations(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, role text not null check(role in ('user','assistant')), content text not null default '', attachments jsonb not null default '[]'::jsonb, created_at timestamptz not null default now());
alter table public.koda_conversations enable row level security;
alter table public.koda_messages enable row level security;
create policy "Users manage own KODA conversations" on public.koda_conversations for all to authenticated using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "Users manage own KODA messages" on public.koda_messages for all to authenticated using(auth.uid()=user_id) with check(auth.uid()=user_id);
create index if not exists koda_conversations_user_updated on public.koda_conversations(user_id,updated_at desc);
create index if not exists koda_messages_conversation_created on public.koda_messages(conversation_id,created_at);